using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using AnimalArchive.Voyage;
public static class VoyageVerification {
 static int checks;static void Check(bool ok,string s){checks++;if(!ok)throw new Exception("V7 CHECK FAILED: "+s);}
 static VoyageConfig Config()=>JsonUtility.FromJson<VoyageConfig>(File.ReadAllText("Assets/Resources/Voyage/config.json"));
 [MenuItem("Animal Archive/V7 Verify play styles")]
 public static void Run(){checks=0;var cfg=Config();var m=new VoyageModel(cfg);for(int i=0;i<8;i++)m.Tick(.1f);Check(m.state.active.Count>0&&m.state.total==0,"spawn gives no points");var p=m.state.active[0];Check(!m.Settle(p),"no payment before door");Check(m.Tap(.5f,.6f)&&m.state.total==0,"tap produces action not fake payment");Check(!m.Tap(.5f,.6f),"tap rate bounded");p.age=p.duration;Check(m.Settle(p)&&!m.Settle(p),"exactly once arrival");Check(m.Discovered==1,"discovery");Check(VoyageModel.Validate(cfg,m.state,out _),"valid ledger");
  for(int i=0;i<200;i++)m.Tick(.1f);string save=VoyageSave.Encode(m.state);var copy=VoyageSave.Decode(cfg,save);Check(copy!=null,"load valid checksum");Check(VoyageSave.Decode(cfg,save.Substring(0,save.Length/2))==null,"reject truncated save");var resumed=new VoyageModel(cfg,copy);for(int i=0;i<100;i++){m.Tick(.1f);resumed.Tick(.1f);}Check(JsonUtility.ToJson(m.state)==JsonUtility.ToJson(resumed.state),"deterministic reload including queue");
  var idle=new VoyageModel(cfg);var active=new VoyageModel(cfg);for(int i=0;i<1200;i++){idle.Tick(.1f);active.Tick(.1f);if(i%2==0){var target=active.state.active.FirstOrDefault(a=>a.age>=0&&!a.admitted&&a.berth<0);if(target!=null)active.Tap(target.x,target.y);}if(i%100==0)active.CallGuide();idle.events.Clear();active.events.Clear();}Check(idle.state.total>0,"automation from first second");Check(active.state.boarded>=idle.state.boarded*.95,"active preserves supply-limited income without upgrades; saturated throughput checked separately");Check(active.state.total==active.state.available+active.state.spent,"active ledger");
  var rich=new VoyageModel(cfg,new VoyageState{total=100000,available=100000});int lanes=rich.Lanes;Check(rich.Buy(2)&&rich.Lanes>lanes,"dock upgrade increases real capacity");float radius=rich.SkillRadius;Check(rich.Buy(3)&&rich.SkillRadius>radius&&rich.Shelter(),"human skill growth and shelter");Check(!rich.Shelter(),"shelter cooldown");
  var crisis=new VoyageModel(cfg,new VoyageState{boarded=320,nextId=320,paidPrefix=320,total=10000,available=10000});crisis.Tick(.1f);Check(crisis.CrisisActive,"crisis trigger");for(int i=0;i<920;i++)crisis.Tick(.1f);Check(crisis.state.crisis==2,"unattended storm recoverable");Check(crisis.LightLantern()&&crisis.state.protection,"permanent protection");
  var flow=new VoyageModel(cfg,new VoyageState{total=100000,available=100000,levels=new[]{6,5,5,5}});int rampSteps=0;bool allMoved=true;for(int tick=0;tick<2400;tick++){var before=flow.state.active.ToDictionary(a=>a.id,a=>a.age);flow.Tick(.1f);foreach(var animal in flow.state.active)if(before.TryGetValue(animal.id,out var age)&&age>=animal.duration*.78f){allMoved&=animal.age>age;rampSteps++;}flow.events.Clear();flow.arrivals.Clear();}Check(rampSteps>100&&allMoved,"dense bridge continuously advances");Check(VoyageModel.Validate(cfg,flow.state,out _),"dense flow ledger");
  Check(VoyageModel.SpeciesSpeed(3)>VoyageModel.SpeciesSpeed(8)*1.8f,"rabbit materially faster than turtle");Check(VoyageModel.StormSpeed(5)==1&&VoyageModel.StormSpeed(1)<.6f,"water resistant and timid species differ");
  for(int level=0;level<=5;level++)foreach(float lane in new[]{-.86f,0,.86f}){var animal=new Passenger{duration=10,age=10,dockLevel=level,lane=lane/.86f};Check(Vector2.Distance(VoyageModel.Position(animal),VoyageModel.Door(level,lane)+new Vector2(.006f,-.015f))<.0001f,"shared door alignment "+level);}
  Vector2 freeTarget=VoyageModel.GuideTarget(.1f,.8f);Check(freeTarget.x==.1f&&freeTarget.y==.8f,"guide may use open left land");Check(VoyageModel.GuideTarget(.85f,.44f).y>.7f,"shoreline constrains water visibly");
  var report=new System.Text.StringBuilder("V9 legacy regression: simulated model play-style comparison (NOT browser playthrough)\n");report.AppendLine("120 sec unupgraded: idle "+idle.state.boarded+" animals / "+idle.state.total+"; active "+active.state.boarded+" / "+active.state.total);
  foreach(int style in new[]{0,1,2}){var sim=new VoyageModel(cfg);float nextBuy=0;long drainId=-1;while(sim.state.elapsed<2400&&!sim.state.completed){sim.Tick(.1f);int tick=(int)(sim.state.elapsed*10);if(style>0&&tick%(style==2?2:12)==0){var target=sim.state.active.FirstOrDefault(a=>a.age>=0&&!a.admitted);Vector2 at=target==null?new Vector2(.5f,.6f):VoyageModel.Position(target);sim.Tap(at.x,at.y);}if(style>0&&sim.state.guideCooldown<=0)sim.CallGuide();if(style>0&&sim.CrisisActive){sim.MoveGuide(.58f,.65f);sim.Shelter();}if(sim.state.elapsed>=nextBuy){nextBuy=sim.state.elapsed+(style==0?8:style==1?3:1);if(sim.TwilightReady)sim.LightLantern();int choice=-1;long cost=long.MaxValue;for(int k=0;k<4;k++)if(sim.Unlocked(k)&&sim.Cost(k)>=0&&sim.Cost(k)<=sim.state.available&&sim.Cost(k)<cost){choice=k;cost=sim.Cost(k);}if(choice>=0)sim.Buy(choice);if(sim.CanSail){Check(sim.RequestSail(),"request sail");drainId=sim.state.nextId;}}sim.events.Clear();sim.arrivals.Clear();}
   Check(sim.state.completed,"style completes "+style);Check(sim.state.active.Count==0&&sim.state.nextId==drainId,"stop spawns and drain "+style);Check(VoyageModel.Validate(cfg,sim.state,out var why),"ledger "+style+" "+why);long ending=sim.state.endTotal;sim.Continue();for(int i=0;i<200;i++)sim.Tick(.1f);Check(sim.state.endTotal==ending,"freeplay preserves ending");report.AppendLine("style "+style+" (0=idle with purchases,1=casual,2=active): "+sim.state.endTime.ToString("F1")+"s; "+sim.state.endBoarded+" boarded; "+ending+" points; peak "+sim.state.peakActive);}
  report.AppendLine("PASS "+checks+" meaningful checks");Directory.CreateDirectory("../Evidence/V102");File.WriteAllText("../Evidence/V102/regression-verification.txt",report.ToString());Debug.Log(report.ToString());
 }
}

